await db.transaction(async (tx) => {
	const seen = await tx.execute(sql`SELECT 1 FROM processed WHERE message_id = ${id}`);
	if (seen.length > 0) return; // duplicata
	await tx.execute(sql`UPDATE accounts SET balance = balance - ${amount} WHERE id = ${accountId}`);
	await tx.execute(sql`INSERT INTO processed (message_id) VALUES (${id})`);
});

